GRANT SELECT ON "AISharingPolicy" TO resolve_evidence,resolve_evidence_test;CREATE POLICY preparer ON "AISharingPolicy" TO resolve_evidence,resolve_evidence_test USING("merchantId"=NULLIF(current_setting('app.merchant_id',true),'')::uuid AND EXISTS(SELECT 1 FROM "EvidenceWorkerTenant" w WHERE w."merchantId"="AISharingPolicy"."merchantId" AND w."roleName"=current_user)) WITH CHECK("merchantId"=NULLIF(current_setting('app.merchant_id',true),'')::uuid AND EXISTS(SELECT 1 FROM "EvidenceWorkerTenant" w WHERE w."merchantId"="AISharingPolicy"."merchantId" AND w."roleName"=current_user));
GRANT UPDATE ON "AIContext" TO resolve_evidence,resolve_evidence_test;GRANT INSERT ON "EvidenceExtraction","EvidenceChunk" TO resolve_evidence,resolve_evidence_test;GRANT SELECT ON "EvidenceChunk" TO resolve_evidence,resolve_evidence_test;
CREATE POLICY preparer_chunks ON "EvidenceChunk" TO resolve_evidence,resolve_evidence_test USING("merchantId"=NULLIF(current_setting('app.merchant_id',true),'')::uuid AND EXISTS(SELECT 1 FROM "EvidenceWorkerTenant" w WHERE w."merchantId"="EvidenceChunk"."merchantId" AND w."roleName"=current_user)) WITH CHECK("merchantId"=NULLIF(current_setting('app.merchant_id',true),'')::uuid AND EXISTS(SELECT 1 FROM "EvidenceWorkerTenant" w WHERE w."merchantId"="EvidenceChunk"."merchantId" AND w."roleName"=current_user));
GRANT SELECT,INSERT ON "OutboxEvent" TO resolve_runtime,resolve_test;
CREATE POLICY ai_outbox ON "OutboxEvent" TO resolve_runtime,resolve_test USING("merchantId"=NULLIF(current_setting('app.merchant_id',true),'')::uuid AND "eventType" IN ('ai.prepare','ai.analyze') AND (case_member("merchantId") OR EXISTS(SELECT 1 FROM "AIContext" c WHERE c.id="OutboxEvent"."aggregateId"))) WITH CHECK("merchantId"=NULLIF(current_setting('app.merchant_id',true),'')::uuid AND "eventType" IN ('ai.prepare','ai.analyze') AND (case_member("merchantId") OR EXISTS(SELECT 1 FROM "AIContext" c WHERE c.id="OutboxEvent"."aggregateId")));
-- Fixed-scope freshness helpers never expose payment records to inference roles.
CREATE FUNCTION ai_manifest_raw(p_case uuid) RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,public AS $$
 SELECT jsonb_build_object('case',jsonb_build_object('id',c.id,'version',c.version,'status',c.status,'policyVersionId',c."policyVersionId"),'order',jsonb_build_object('id',o.id,'version',o.version,'status',o.status,'paymentState',o."paymentState",'amount',o."amountMinor"::text,'currency',o.currency),'capture',(SELECT jsonb_build_object('id',p.id,'version',p.version,'status',p."providerStatus",'reconciliation',p."reconciliationStatus",'gross',p."grossMinor"::text,'reserved',p."reservedMinor"::text,'refunded',p."refundedMinor"::text,'external',p."externalRefundedMinor"::text,'verifiedAt',p."verifiedAt") FROM public."Capture" p WHERE p."merchantId"=c."merchantId" AND p."orderId"=c."orderId"),'policy',(SELECT jsonb_build_object('id',v.id,'hash',v."contentHash") FROM public."PolicyVersion" v WHERE v.id=c."policyVersionId"),'evidence',COALESCE((SELECT jsonb_agg(jsonb_build_object('id',e.id,'hash',e.sha256,'scan',e."scanStatus",'upload',e."uploadState",'cleanKey',e."cleanObjectKey",'scannedAt',e."scannedAt") ORDER BY e.id) FROM public."Evidence" e WHERE e."caseId"=c.id AND e."merchantId"=c."merchantId"),'[]'::jsonb),'comments',COALESCE((SELECT jsonb_agg(jsonb_build_object('id',n.id,'body',n.body) ORDER BY n.id) FROM public."CaseComment" n WHERE n."caseId"=c.id AND n.visibility='CUSTOMER'),'[]'::jsonb),'timeline',COALESCE((SELECT jsonb_agg(t.id ORDER BY t.id) FROM public."CaseTimelineEvent" t WHERE t."caseId"=c.id AND t.visibility='CUSTOMER' AND t.action NOT LIKE 'AI_%'),'[]'::jsonb)) FROM public."Case" c JOIN public."Order" o ON o.id=c."orderId" AND o."merchantId"=c."merchantId" WHERE c.id=p_case;
$$;
REVOKE ALL ON FUNCTION ai_manifest_raw(uuid) FROM PUBLIC;
CREATE FUNCTION ai_visible_manifest(p_case uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$DECLARE c public."Case";u uuid:=NULLIF(current_setting('app.user_id',true),'')::uuid;m uuid:=NULLIF(current_setting('app.merchant_id',true),'')::uuid;BEGIN
 SELECT * INTO c FROM public."Case" WHERE id=p_case AND "merchantId"=m;
 IF c.id IS NULL OR NOT(c."openedBy"=u OR EXISTS(SELECT 1 FROM public."Membership" WHERE "merchantId"=m AND "userId"=u AND active)) THEN RAISE EXCEPTION 'Unauthorized AI scope';END IF;
 RETURN public.ai_manifest_raw(p_case);END$$;
REVOKE ALL ON FUNCTION ai_visible_manifest(uuid) FROM PUBLIC;GRANT EXECUTE ON FUNCTION ai_visible_manifest(uuid) TO resolve_runtime,resolve_test;
CREATE FUNCTION ai_context_fresh(p_context uuid) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$DECLARE c public."AIContext";u uuid:=NULLIF(current_setting('app.user_id',true),'')::uuid;m uuid:=NULLIF(current_setting('app.merchant_id',true),'')::uuid;BEGIN
 SELECT * INTO c FROM public."AIContext" WHERE id=p_context AND "merchantId"=m;
 IF c.id IS NULL THEN RETURN false;END IF;
 IF NOT(EXISTS(SELECT 1 FROM public."AIWorkerTenant" WHERE "merchantId"=m AND "roleName"=session_user) OR EXISTS(SELECT 1 FROM public."EvidenceWorkerTenant" WHERE "merchantId"=m AND "roleName"=session_user) OR EXISTS(SELECT 1 FROM public."Case" ca WHERE ca.id=c."caseId" AND (ca."openedBy"=u OR EXISTS(SELECT 1 FROM public."Membership" WHERE "merchantId"=m AND "userId"=u AND active)))) THEN RETURN false;END IF;
 PERFORM p.id FROM public."Capture" p JOIN public."Case" ca ON ca."orderId"=p."orderId" AND ca."merchantId"=p."merchantId" WHERE ca.id=c."caseId" FOR SHARE OF p;
 PERFORM id FROM public."Case" WHERE id=c."caseId" FOR UPDATE;
 PERFORM id FROM public."Evidence" WHERE "caseId"=c."caseId" ORDER BY id FOR SHARE;
 RETURN c."manifest"=public.ai_manifest_raw(c."caseId") AND c."expiresAt">now() AND c.state IN ('QUEUED','PREPARING','READY') AND c."sharingPolicyId"=(SELECT id FROM public."AISharingPolicy" WHERE "merchantId"=m ORDER BY sequence DESC LIMIT 1) AND EXISTS(SELECT 1 FROM public."AISharingPolicy" WHERE id=c."sharingPolicyId" AND enabled);
END$$;
REVOKE ALL ON FUNCTION ai_context_fresh(uuid) FROM PUBLIC;GRANT EXECUTE ON FUNCTION ai_context_fresh(uuid) TO resolve_runtime,resolve_test,resolve_ai,resolve_ai_test,resolve_evidence,resolve_evidence_test;
CREATE FUNCTION guard_ai_context() RETURNS trigger LANGUAGE plpgsql AS $$BEGIN
 IF OLD.state='READY' AND (NEW."requestEncrypted",NEW."catalogEncrypted",NEW."consentHash",NEW.manifest,NEW."baseEncrypted",NEW."sharingPolicyId",NEW."selectedEvidenceIds",NEW."caseId",NEW."merchantId") IS DISTINCT FROM (OLD."requestEncrypted",OLD."catalogEncrypted",OLD."consentHash",OLD.manifest,OLD."baseEncrypted",OLD."sharingPolicyId",OLD."selectedEvidenceIds",OLD."caseId",OLD."merchantId") THEN RAISE EXCEPTION 'Ready AI context immutable';END IF;RETURN NEW;END$$;
CREATE TRIGGER ai_context_guard BEFORE UPDATE ON "AIContext" FOR EACH ROW EXECUTE FUNCTION guard_ai_context();
CREATE FUNCTION guard_ai_result() RETURNS trigger LANGUAGE plpgsql AS $$BEGIN
 IF OLD."contextId" IS NOT NULL AND (NEW."contextId",NEW."consentId",NEW."snapshotHash",NEW."snapshotJson",NEW."modelId",NEW."promptVersion",NEW."schemaVersion",NEW."policyEngineVersion",NEW."caseId",NEW."merchantId",NEW."requestedBy") IS DISTINCT FROM (OLD."contextId",OLD."consentId",OLD."snapshotHash",OLD."snapshotJson",OLD."modelId",OLD."promptVersion",OLD."schemaVersion",OLD."policyEngineVersion",OLD."caseId",OLD."merchantId",OLD."requestedBy") THEN RAISE EXCEPTION 'AI input immutable';END IF;
 IF OLD."outputEncrypted" IS NOT NULL AND NEW."outputEncrypted" IS DISTINCT FROM OLD."outputEncrypted" THEN RAISE EXCEPTION 'AI output immutable';END IF;RETURN NEW;END$$;
CREATE TRIGGER ai_result_guard BEFORE UPDATE ON "Analysis" FOR EACH ROW EXECUTE FUNCTION guard_ai_result();
CREATE INDEX ai_context_due ON "AIContext"(state,"nextAttemptAt");CREATE INDEX ai_analysis_due ON "Analysis"(status,"nextAttemptAt");
CREATE FUNCTION guard_ai_source() RETURNS trigger LANGUAGE plpgsql AS $$DECLARE o uuid;BEGIN
 SELECT "orderId" INTO o FROM public."Case" WHERE id=NEW."caseId" AND "merchantId"=NEW."merchantId";
 IF NEW."caseSourceId" IS NOT NULL AND NEW."caseSourceId"<>NEW."caseId" THEN RAISE EXCEPTION 'Wrong case source';END IF;
 IF NEW."orderId" IS NOT NULL AND NEW."orderId"<>o THEN RAISE EXCEPTION 'Wrong order source';END IF;
 IF NEW."captureId" IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public."Capture" WHERE id=NEW."captureId" AND "orderId"=o AND "merchantId"=NEW."merchantId") THEN RAISE EXCEPTION 'Wrong capture source';END IF;RETURN NEW;END$$;
CREATE TRIGGER ai_source_guard BEFORE INSERT ON "AnalysisSource" FOR EACH ROW EXECUTE FUNCTION guard_ai_source();
CREATE OR REPLACE FUNCTION guard_immutable_content() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog,public AS $$
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Immutable content'; END IF;
 IF TG_TABLE_NAME='Proposal' AND (to_jsonb(NEW)-ARRAY['status','rowVersion','completedAt']) IS DISTINCT FROM (to_jsonb(OLD)-ARRAY['status','rowVersion','completedAt']) THEN RAISE EXCEPTION 'Immutable proposal content'; END IF;
 IF TG_TABLE_NAME='PolicyVersion' AND (to_jsonb(OLD)->>'publishedAt') IS NOT NULL AND to_jsonb(NEW) IS DISTINCT FROM to_jsonb(OLD) THEN RAISE EXCEPTION 'Published policy is immutable'; END IF;
 IF TG_TABLE_NAME='Analysis' AND (to_jsonb(OLD)->>'status')='SUCCEEDED' AND (to_jsonb(NEW)-ARRAY['status','version','leaseOwner','leaseUntil','nextAttemptAt','lastErrorCode']) IS DISTINCT FROM (to_jsonb(OLD)-ARRAY['status','version','leaseOwner','leaseUntil','nextAttemptAt','lastErrorCode']) THEN RAISE EXCEPTION 'Successful analysis is immutable'; END IF;
 IF TG_TABLE_NAME='Evidence' AND (to_jsonb(OLD)->>'scanStatus')='CLEAN' AND (to_jsonb(NEW)->'objectKey',to_jsonb(NEW)->'objectVersion',to_jsonb(NEW)->'sha256') IS DISTINCT FROM (to_jsonb(OLD)->'objectKey',to_jsonb(OLD)->'objectVersion',to_jsonb(OLD)->'sha256') THEN RAISE EXCEPTION 'Validated evidence is immutable'; END IF;
 RETURN NEW;
END $$;
